"""
pmo_raise.py — PMO Automation for Vector
Extracts data from PDFs, fills baked-in template using XML editing,
outputs filled docx path on __DOCX__:<path> line.
"""
import os, sys, re, zipfile, base64, tempfile
from datetime import datetime

try: import openpyxl
except ImportError:
    print("[ERR] openpyxl not installed.", flush=True); sys.exit(1)
try: import pdfplumber
except ImportError:
    print("[ERR] pdfplumber not installed.", flush=True); sys.exit(1)

QUOTE_PDF     = os.environ.get("MAGIC_PMO_QUOTE_PDF", "")
PO_PDF        = os.environ.get("MAGIC_PMO_PO_PDF", "")
_DOCU_RAW     = os.environ.get("MAGIC_PMO_DOCU_PDFS", os.environ.get("MAGIC_PMO_PRICE_PDF", ""))
DOCU_PDFS     = [p for p in _DOCU_RAW.split("|") if p.strip() and os.path.exists(p.strip())]
PMO_LOG       = os.environ.get("MAGIC_PMO_LOG", r"Z:\_PMO-Pending Folder\PMO LOG-2012 V1.xlsx")
SEQ_OVERRIDE  = os.environ.get("MAGIC_PMO_SEQ", "").strip()
INITIALS      = os.environ.get("MAGIC_PMO_INITIALS", "LS")
SALES_CONTACT = os.environ.get("MAGIC_PMO_SALES_CONTACT", "Sharron James")

TEMPLATE_B64 = ""

def log(msg): print(msg, flush=True)

def parse_price(s):
    s = re.sub(r'[\u20ac\xa3$,\s]', '', str(s).strip())
    try: return float(s)
    except ValueError: return 0.0

def xml_escape(s):
    return (str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
             .replace('"','&quot;').replace("\'",'&apos;'))

def make_run(text, bold=False, sz=22, font="Arial", color=None):
    rpr = [f'<w:rFonts w:cs="{font}"/>', f'<w:sz w:val="{sz}"/>', f'<w:szCs w:val="{sz}"/>']
    if bold: rpr += ['<w:b/>', '<w:bCs/>']
    if color: rpr.append(f'<w:color w:val="{color}"/>')
    rpr_xml = "<w:rPr>" + "".join(rpr) + "</w:rPr>"
    return f'<w:r>{rpr_xml}<w:t xml:space="preserve">{xml_escape(text)}</w:t></w:r>'

def replace_para(xml, para_id, *runs):
    pattern = re.compile(
        r'(<w:p\s[^>]*w14:paraId="' + re.escape(para_id) + r'"[^>]*>)(.*?)(</w:p>)',
        re.DOTALL)
    def repl(m):
        inner = m.group(2)
        ppr_m = re.search(r'<w:pPr>.*?</w:pPr>', inner, re.DOTALL)
        ppr   = ppr_m.group(0) if ppr_m else ""
        return m.group(1) + ppr + "".join(runs) + m.group(3)
    return pattern.sub(repl, xml)

def extract_quote(pdf_path):
    """
    Extract header data from an Eaton BidManager quote / Intermediate Bill of Material PDF.
    Handles both old-style (QB…) and SF-style (SR…) quotation references.
    """
    log(f"[*] Quote PDF: {os.path.basename(pdf_path)}")
    pages = []
    with pdfplumber.open(pdf_path) as pdf:
        for p in pdf.pages: pages.append(p.extract_text() or "")
    full = "\n".join(pages)
    d = {}

    # DWO / quotation reference  →  "QUOTATION REF: SR00BIXf7YAH"
    m = re.search(r'QUOTATION REF:\s*(\S+)', full)
    d["dwo_ref"] = m.group(1).strip() if m else ""

    # Project name  →  "Project Reference: SR00BIXf7YAH A The Chimes shopping centre …"
    # Strip the leading QB/SR ref token and any single-letter revision letter (e.g. "A ")
    m = re.search(r'Project Reference:\s*\S+\s+(?:[A-Z]\s+)?(.+)', full)
    if m:
        # May continue on the next line (pdfplumber wraps long lines)
        raw = m.group(1).strip()
        # Grab continuation line if the match ended mid-sentence
        end_pos = m.end()
        rest = full[end_pos:end_pos+120].split('\n')
        if rest and rest[0].strip() and not re.match(r'^[A-Z]', rest[0].strip()):
            raw += ' ' + rest[0].strip()
        d["project_name"] = raw.strip()
        d["enquiry_seq"]  = d.get("dwo_ref", "")
    else:
        d["enquiry_seq"]  = d.get("dwo_ref", "")
        d["project_name"] = ""

    # Issue date
    m = re.search(r'Issue Date:\s*([\d/]+)', full)
    d["date_sent"] = m.group(1).strip() if m else datetime.today().strftime("%d/%m/%Y")

    # Salesman — split email address at boundary to reconstruct name
    m = re.search(r'Sales Engineer for this Project,\s*([\w.]+@eaton\.com)', full, re.IGNORECASE)
    if m:
        local = m.group(1).split("@")[0].lower()
        best = local.title()
        best_score = -1
        for i in range(3, len(local) - 2):
            p1, p2 = local[:i], local[i:]
            if len(p1) >= 3 and len(p2) >= 3:
                score = len(p2)
                if score > best_score:
                    best_score = score
                    best = f"{p1.title()} {p2.title()}"
        d["salesman"] = best
    else:
        d["salesman"] = ""

    # Project total  →  "Total Quote Price ( GBP ) 133,636.16"
    # Also try "Total Plant Price" for older format
    m = (re.search(r'Total Quote Price\s*\(\s*GBP\s*\)\s*([\d,]+\.\d{2})', full) or
         re.search(r'Total Plant Price\s*\(\s*GBP\s*\)\s*([\d,]+\.\d{2})', full))
    d["project_value"] = m.group(1) if m else ""

    # Fallback fields expected by template
    for k in ["qty", "description", "sell_price", "cat_ref"]:
        d.setdefault(k, "")

    log(f"  DWO: {d.get('dwo_ref')}  Project: {d.get('project_name')}")
    log(f"  Date: {d.get('date_sent')}  Salesman: {d.get('salesman')}  Value: \xa3{d.get('project_value')}")
    return d

def extract_price(pdf_path):
    """Extract NTP, ACP, Cat Ref, description and qty from a single DOCU_ID PDF."""
    log(f"[*] DOCU PDF: {os.path.basename(pdf_path)}")
    result = {"ntp": "", "acp": "", "cat_ref": "", "description": "", "qty": ""}
    with pdfplumber.open(pdf_path) as pdf:
        for p in pdf.pages:
            t = p.extract_text() or ""

            # Cat Ref — "DESIGNATION QB28154-S8 Right hand side" (all-caps label)
            if not result["cat_ref"]:
                m = re.search(r'^DESIGNATION\s+(.+)$', t, re.MULTILINE)
                if not m:
                    m = re.search(r'^Designation\s+(.+)$', t, re.MULTILINE)
                if m:
                    val = m.group(1).strip()
                    # Ignore if it's a generic title line (>60 chars or no alphanumeric pattern)
                    if val and len(val) <= 80:
                        result["cat_ref"] = val

            # Description — "Cabinet type: DualGuard-S 12C" or "Cabinet: DualGuard-S 12C"
            if not result["description"]:
                m = re.search(r'Cabinet type:\s+(DualGuard[^\n]+)', t)
                if not m:
                    m = re.search(r'Cabinet:\s+(DualGuard[^\n]+)', t)
                if m:
                    result["description"] = m.group(1).strip()

            # Qty — "Number of identical cabinets: 2"  (often blank → default 1)
            if not result["qty"]:
                m = re.search(r'Number of identical cabinets:\s*(\d+)', t)
                result["qty"] = m.group(1).strip() if m else "1"

            # NTP + ACP on same line: "Total Price with €26,128.30 Total Cost €4,392.12 83.19"
            if not result["ntp"] and "Bill of Material Summary" in t:
                m = re.search(
                    r'Total Price with\s+[\u20ac\xa3]?([\d,]+\.\d{2})\s+Total Cost\s+[\u20ac\xa3]?([\d,]+\.\d{2})',
                    t)
                if m:
                    result["ntp"] = m.group(1)
                    result["acp"] = m.group(2)
                else:
                    # Fallback: separate lines
                    m1 = re.search(r'Total Price with[^\n]*[\u20ac\xa3]([\d,]+\.\d{2})', t)
                    m2 = re.search(r'Total Cost[^\n]*[\u20ac\xa3]([\d,]+\.\d{2})', t)
                    if m1: result["ntp"] = m1.group(1)
                    if m2: result["acp"] = m2.group(1)

    log(f"  Cat Ref: {result['cat_ref']}  Desc: {result['description']}  Qty: {result['qty']}")
    log(f"  NTP: \u20ac{result['ntp']}  ACP: \u20ac{result['acp']}")
    return result


def _strip_quote_prefix(s):
    """
    Strip leading quote-reference prefixes so only the meaningful
    system-identity tokens remain.
    Handles both old-style (QB28150-S9) and SF-style (SR00BIXf7YAH-S9).
    Also strips the -SN suffix ONLY from the prefix, not from other tokens.
    """
    # Remove QB28150-S9 or SR00BIXf7YAH-S9 style prefix (alphanumeric run, dash, S+digits)
    s = re.sub(r'\b(?:QB|SR)[A-Za-z0-9]+-S\d+\b', '', s, flags=re.IGNORECASE)
    # Remove any remaining lone QB/SR ids without the suffix
    s = re.sub(r'\b(?:QB|SR)[A-Za-z0-9]+\b', '', s, flags=re.IGNORECASE)
    return s.strip(' -–')


def _system_tokens(s):
    """
    Return a frozenset of meaningful uppercase tokens from a designation string.
    Strips quote-ref prefixes (QB / SR style) and ignores stop-words.
    Numbers like '10', '1' are kept as they identify the system index.
    """
    s = _strip_quote_prefix(s)
    tokens = re.findall(r'[A-Za-z0-9]+', s)
    # Drop single-char tokens and generic stop-words
    stop = {'OF', 'IN', 'TO', 'FOR', 'THE', 'AND', 'A', 'AT'}
    return frozenset(
        t.upper() for t in tokens
        if len(t) >= 2 and t.upper() not in stop
    )


def _token_score(s1, s2):
    """
    Flexible Jaccard similarity between two designation strings.
    Tries the raw strings AND all 2-word-swap permutations to handle
    different word orderings (e.g. 'EMS1 ZB96 System 1' vs 'ZB96 System 1 EMS1').
    Returns the best score found.
    """
    t1 = _system_tokens(s1)
    t2 = _system_tokens(s2)
    if not t1 or not t2:
        return 0.0
    union = t1 | t2
    if not union:
        return 0.0
    return len(t1 & t2) / len(union)


def _is_main_system_line(description):
    """
    Return True if this quote line item is the primary DualGuard/LoadStar unit,
    not a supplementary item (MTZ surcharge, battery build, commissioning, IDLS, etc.).
    """
    desc = description.upper()
    # Must contain a product identifier
    if not any(k in desc for k in ('DG-S', 'DUALGUARD', 'DG S', 'LOADSTAR')):
        return False
    # Exclude known supplementary lines
    for excl in ('MTZ', 'BATTERY BUILD', 'COMMISSIONING', 'IDLS', 'SURCHARGE',
                 'NEXITECH', 'PICTO', 'LEGEND', 'LUMINAIRE'):
        if excl in desc:
            return False
    return True


def extract_quote_items(pdf_path):
    """
    Extract DualGuard system items from an Eaton Intermediate Bill of Material PDF.

    Two system types:
    A) Product = 'DualGuard-S'  (standard 4C3)
       Line:  '<item_no> <qty> DualGuard-S <desc> <unit_price> <ext_price>'
       Next:  'Product Group H51'
       Next:  'Designation QB28150-S1 ZB96 - System 1 EMS1'

    B) Product = 'Cooper CBU', description starts with 'DualGuard-S 12C'  (special configs)
       Line:  '<item_no> <qty> Cooper CBU DualGuard-S 12C - ... <unit_price> <ext_price>'
       Next:  'Catalog No QB28150-S6 ZB96 - System'
       Next:  'Designation QB28150-S6 ZB96 - System 7 EMZ4'
    """
    log(f"[*] Extracting quote items: {os.path.basename(pdf_path)}")
    items = []
    pages = []
    with pdfplumber.open(pdf_path) as pdf:
        for p in pdf.pages: pages.append(p.extract_text() or "")

    # Regex: item_no (3-5 digits), qty, product, description, unit_price (ext_price ignored)
    ITEM_RE = re.compile(
        r'^(\d{3,5})\s+(\d+)\s+(DualGuard-S|Cooper CBU)\s+(.+?)\s+([\d,]+\.\d{2})\s+[\d,]+\.\d{2}\s*$'
    )

    for page_text in pages:
        lines = page_text.split('\n')
        for li, line in enumerate(lines):
            line = line.strip()
            m = ITEM_RE.match(line)
            if not m:
                continue

            item_no  = m.group(1)
            qty      = m.group(2)
            product  = m.group(3)
            desc     = m.group(4).strip()
            price    = m.group(5).replace(',', '')

            # Keep only: DualGuard-S product rows, OR Cooper CBU rows with DG12C in description
            is_dg_product = (product == 'DualGuard-S')
            is_dg12c_cbu  = (product == 'Cooper CBU' and
                             re.search(r'DualGuard-S\s+12C', desc, re.IGNORECASE))
            if not (is_dg_product or is_dg12c_cbu):
                continue

            # Scan forward up to 8 lines for Designation
            designation = ''
            for sl in lines[li+1 : li+9]:
                sl = sl.strip()
                dm = re.match(r'^Designation\s+(.+)$', sl, re.IGNORECASE)
                if dm:
                    val = dm.group(1).strip()
                    # Skip generic labels
                    if val and not any(v in val.lower() for v in
                                       ('battery', 'commissioning', 'qty tbc', 'surcharge', 'install')):
                        designation = val
                    break

            item = {
                'item_no':     item_no,
                'qty':         qty,
                'product':     product,
                'description': desc,
                'sell_price':  price,
                'designation': designation,
                'catalog_no':  '',
            }
            items.append(item)
            log(f"  Item {item_no} [{product}]: \xa3{price}  Desig: {designation or '(none)'}  [{desc[:45]}]")

    log(f"  → {len(items)} system item(s) found in quote")
    return items


def match_docu_to_quote(docu_items, quote_items):
    """
    Match each DOCU item to a quote line item using flexible token overlap.
    Both QB-style and SR-style prefixes are stripped before comparison.
    Returns docu_items enriched with sell_price from the best matching quote item.
    """
    claimed = set()
    result  = []
    for item in docu_items:
        item    = dict(item)
        cat_ref = item.get('cat_ref', '')

        best_score = 0.0
        best_idx   = None
        for qi, qitem in enumerate(quote_items):
            if qi in claimed:
                continue
            # Score against both the designation and the catalog_no fields
            score = max(
                _token_score(cat_ref, qitem.get('designation', '')),
                _token_score(cat_ref, qitem.get('catalog_no', '')),
            )
            if score > best_score:
                best_score = score
                best_idx   = qi

        if best_idx is not None and best_score >= 0.25:
            qitem = quote_items[best_idx]
            claimed.add(best_idx)
            item['sell_price']        = qitem['sell_price']
            item['sell_price_quote']  = qitem['sell_price']
            item['quote_designation'] = qitem['designation']
            item['po_match']          = 'Quote matched'
            item['po_ok']             = True
            item['po_note']           = (f"Matched (score {best_score:.2f}): "
                                         f"{qitem['designation'] or qitem['catalog_no']}")
            log(f"  [OK] CatRef '{cat_ref}' → Quote '{qitem['designation']}' "
                f"(score {best_score:.2f}) £{qitem['sell_price']}")
        else:
            item.setdefault('sell_price', '')
            item['po_match'] = 'No quote match'
            item['po_ok']    = False
            item['po_note']  = f"No quote line matched (best score {best_score:.2f})"
            log(f"  [WARN] No quote match for '{cat_ref}' (best score {best_score:.2f})")

        result.append(item)
    return result


def _read_po_text(pdf_path):
    log(f"[*] PO PDF: {os.path.basename(pdf_path)}")
    with pdfplumber.open(pdf_path) as pdf:
        return "\n".join(p.extract_text() or "" for p in pdf.pages)


def match_items_to_po(po_text, items):
    """
    Given a list of item dicts (each with cat_ref, qty, sell_price_quote),
    match each to a unique PO line and return enriched dicts.
    Strategy: try Cat Ref first, then DualGuard line by qty, then any unclaimed line.
    """
    # Pre-collect all DualGuard lines from PO
    po_lines = list(re.finditer(
        r'(\d+)\s+DualGuard[^\n]+?\d{2}/\d{2}/\d{2}\s+([\d,]+\.\d{2})\s+Ea', po_text))
    claimed = set()   # indices into po_lines already assigned

    result = []
    for item in items:
        item = dict(item)
        cat_ref  = item.get("cat_ref", "").strip()
        docu_qty = item.get("qty", "").strip()
        matched_idx   = None
        matched_price = None

        # Pass 1: Cat Ref substring match on the PO line text
        if cat_ref:
            for i, m in enumerate(po_lines):
                if i in claimed: continue
                line_start = max(0, m.start() - 200)
                ctx = po_text[line_start: m.end() + 100]
                if cat_ref in ctx:
                    matched_idx   = i
                    matched_price = m.group(2)
                    break

        # Pass 2: match by equal qty
        if matched_idx is None and docu_qty:
            for i, m in enumerate(po_lines):
                if i in claimed: continue
                if m.group(1) == docu_qty:
                    matched_idx   = i
                    matched_price = m.group(2)
                    break

        # Pass 3: take first unclaimed line
        if matched_idx is None:
            for i, m in enumerate(po_lines):
                if i in claimed: continue
                matched_idx   = i
                matched_price = m.group(2)
                break

        if matched_idx is None:
            log(f"  [WARN] No PO match for Cat Ref: {cat_ref or '(unknown)'}")
            item["po_match"]  = item.get("po_match", "Not found")
            item["po_ok"]     = False
            item["po_note"]   = f"No PO line matched for {cat_ref}"
        else:
            claimed.add(matched_idx)
            po_price = matched_price
            po_p     = parse_price(po_price)
            # If sell_price already set from quote match, cross-check; otherwise use PO price
            existing = item.get("sell_price", "")
            if existing:
                q_p = parse_price(existing)
                if q_p > 0:
                    ok = abs(po_p - q_p) <= q_p * 0.05
                    log(f"  Cat Ref {cat_ref}: PO £{po_p:,.2f}  Quote £{q_p:,.2f}  -> {'OK' if ok else 'MISMATCH'}")
                    if not ok:
                        item["po_match"] = "MISMATCH"
                        item["po_ok"]    = False
                        item["po_note"]  = f"PO £{po_p:,.2f} vs Quote £{q_p:,.2f}"
                    else:
                        item["po_match"] = "OK"
                        item["po_ok"]    = True
                        item["po_note"]  = ""
                else:
                    item["sell_price"] = po_price
                    item["po_match"]   = "OK"
                    item["po_ok"]      = True
                    item["po_note"]    = ""
            else:
                item["sell_price"] = po_price
                item["po_match"]   = "OK"
                item["po_ok"]      = True
                item["po_note"]    = ""
        result.append(item)
    return result


def get_next_cbu(log_path):
    log("[*] Reading PMO log...")
    wb = openpyxl.load_workbook(log_path, data_only=True); ws = wb.active; last = 0
    for row in ws.iter_rows(values_only=True):
        v = row[0]
        if v and isinstance(v,str):
            m = re.match(r'CBU(\d+)', v.strip().upper())
            if m:
                n = int(m.group(1))
                if n > last: last = n
    if last == 0: raise ValueError("No CBU number found in PMO log")
    cbu = f"CBU{last+1}"; log(f"[OK] Next CBU: {cbu}"); return cbu

def add_pmo_row(log_path, cbu, qdata):
    log("[*] Writing to PMO log...")
    wb = openpyxl.load_workbook(log_path); ws = wb.active
    r = ws.max_row
    while r > 1 and ws.cell(r,1).value is None: r -= 1
    r += 1
    ws.cell(r,1).value = cbu; ws.cell(r,2).value = qdata.get("dwo_ref","")
    ws.cell(r,3).value = qdata.get("project_name",""); ws.cell(r,4).value = qdata.get("date_sent","")
    ws.cell(r,6).value = SALES_CONTACT; ws.cell(r,7).value = INITIALS
    wb.save(log_path); log(f"[OK] Row {r} added to PMO log")

def fill_template(cbu, qdata, items, out_path):
    """
    items: list of dicts, each with keys:
      cat_ref, description, qty, sell_price, ntp, acp
    One row per item is inserted into Table 3.
    """
    log("[*] Filling PMO template (XML edit)...")
    raw = base64.b64decode(TEMPLATE_B64)
    tmp_in = out_path + ".tpl.docx"
    with open(tmp_in, 'wb') as f: f.write(raw)
    with zipfile.ZipFile(tmp_in, 'r') as zin:
        files = {n: zin.read(n) for n in zin.namelist()}
    xml = files["word/document.xml"].decode("utf-8")

    from datetime import date as _date
    _t = _date.today()
    gen_date = f"{_t.day}/{_t.month}/{_t.year}"
    seq_cell = SEQ_OVERRIDE if SEQ_OVERRIDE else cbu

    # ── Table 1 ──────────────────────────────────────────────────────────────
    xml = replace_para(xml, "49C0901F", make_run(qdata.get("salesman",""), sz=24))
    xml = replace_para(xml, "0D819634", make_run(gen_date, sz=24))
    xml = replace_para(xml, "3F6C0D73", make_run(seq_cell, bold=True, sz=24, font="Calibri"))

    # ── Table 2 ──────────────────────────────────────────────────────────────
    xml = replace_para(xml, "601FE4D5", make_run(qdata.get("salesman",""), sz=24))
    xml = replace_para(xml, "429AB6AB", make_run(gen_date, sz=24))
    xml = replace_para(xml, "445E8F32", make_run(qdata.get("dwo_ref",""), bold=True, sz=24))
    xml = replace_para(xml, "32322879", make_run(qdata.get("project_name",""), sz=24))
    val = qdata.get("project_value","")
    xml = replace_para(xml, "49477F00", make_run(f"\xa3{val}" if val else "", sz=24))
    xml = replace_para(xml, "56E0030F", make_run(qdata.get("salesman",""), sz=24))

    # ── Table 3: one row per DOCU item ───────────────────────────────────────
    def pr(text, bold=False, sz=20):
        b = '<w:b/><w:bCs/>' if bold else ''
        return (f'<w:r><w:rPr>{b}<w:rFonts w:cs="Arial"/>'
                f'<w:sz w:val="{sz}"/><w:szCs w:val="{sz}"/></w:rPr>'
                f'<w:t xml:space="preserve">{text}</w:t></w:r>')

    def find_para_end(s, para_id):
        start = s.find(f'w14:paraId="{para_id}"')
        if start == -1: return -1, -1
        tag_start = s.rfind('<w:p ', 0, start)
        tag_end   = s.find('</w:p>', start) + len('</w:p>')
        return tag_start, tag_end

    def make_row_xml(item, cat_para_id, qty_para_id, desc_para_ids):
        """Build XML for one table 3 row: cat_ref cell, desc+prices cell, qty cell."""
        cat_xml  = replace_para(xml, cat_para_id,  make_run(xml_escape(item.get("cat_ref","")),  sz=20))
        # We work on a local copy of xml just for the replace, then extract the para
        # Actually we build inline para strings directly:
        ntp  = xml_escape(f"\u20ac{item['ntp']}"        if item.get("ntp")        else "n/a")
        sell = xml_escape(f"\xa3{item['sell_price']}"    if item.get("sell_price") else "n/a")
        acp  = xml_escape(f"\u20ac{item['acp']}"         if item.get("acp")        else "n/a")
        desc = xml_escape(item.get("description",""))
        qty  = xml_escape(item.get("qty",""))

        def cp(para_id, *runs):
            return (f'<w:p w14:paraId="{para_id}" w14:textId="77777777">' +
                    '<w:pPr><w:jc w:val="center"/></w:pPr>' +
                    ''.join(runs) + '</w:p>')

        desc_block = (
            cp(desc_para_ids[0], pr(desc, bold=True)) +
            cp(desc_para_ids[1], pr("NTP: "), pr(ntp, bold=True)) +
            cp(desc_para_ids[2], pr("Sell Out: "), pr(sell, bold=True)) +
            cp(desc_para_ids[3], pr("ACP: "), pr(acp, bold=True))
        )
        qty_block = (
            f'<w:r><w:rPr><w:b/><w:bCs/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr>' +
            f'<w:t>{qty}</w:t></w:r>'
        )
        return desc_block, qty_block

    # The template has one row. For the first item we edit in-place.
    # For additional items we duplicate the row block and append it after.

    # Fill first item into template slots
    first = items[0] if items else {}
    xml = replace_para(xml, "5C6EBDB4", make_run(xml_escape(first.get("cat_ref","")), sz=20))

    ntp0  = xml_escape(f"\u20ac{first['ntp']}"       if first.get("ntp")        else "n/a")
    sell0 = xml_escape(f"\xa3{first['sell_price']}"  if first.get("sell_price") else "n/a")
    acp0  = xml_escape(f"\u20ac{first['acp']}"        if first.get("acp")        else "n/a")
    desc0 = xml_escape(first.get("description",""))
    qty0  = xml_escape(first.get("qty",""))

    def cp(para_id, *runs):
        return (f'<w:p w14:paraId="{para_id}" w14:textId="77777777">' +
                '<w:pPr><w:jc w:val="center"/></w:pPr>' +
                ''.join(runs) + '</w:p>')

    desc_block0 = (
        cp("0FBA467E", pr(desc0, bold=True)) +
        cp("43ACCFF4", pr("NTP: "), pr(ntp0, bold=True)) +
        cp("2752CB92", pr("Sell Out: "), pr(sell0, bold=True)) +
        cp("5980B4E2", pr("ACP: "), pr(acp0, bold=True))
    )

    s0, _ = find_para_end(xml, "0FBA467E")
    _, e1 = find_para_end(xml, "5980B4E2")
    if s0 != -1 and e1 != -1:
        xml = xml[:s0] + desc_block0 + xml[e1:]
    else:
        log("[WARN] Description block not found in template")

    xml = replace_para(xml, "39A81BDE",
        f'<w:r><w:rPr><w:b/><w:bCs/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr>' +
        f'<w:t>{qty0}</w:t></w:r>')

    # For each additional item, locate the table row containing 5C6EBDB4 and clone it
    for idx, item in enumerate(items[1:], start=1):
        # Find the <w:tr> that contains the cat_ref / description / qty cells
        # We identify it by the 5C6EBDB4 anchor (first occurrence left after replacements)
        anchor_tag = '5C6EBDB4'
        # After first item fill, 5C6EBDB4 para is now replaced — find it by its
        # last known text content or scan for the table row containing "ACP:"
        # Easiest: find the <w:tr> that contains "ACP:" text
        acp_idx = xml.rfind('ACP:')
        if acp_idx == -1:
            log(f"[WARN] Cannot find row anchor for item {idx+1}")
            continue
        tr_start = xml.rfind('<w:tr ', 0, acp_idx)
        if tr_start == -1:
            tr_start = xml.rfind('<w:tr>', 0, acp_idx)
        if tr_start == -1:
            log(f"[WARN] Cannot find <w:tr> for item {idx+1}")
            continue
        tr_end = xml.find('</w:tr>', acp_idx) + len('</w:tr>')
        original_row = xml[tr_start:tr_end]

        # Build new row from scratch reusing template row structure
        # Replace cell contents: cat_ref cell, desc cell, qty cell
        import hashlib, random
        def uid(): return format(random.randint(0, 0xFFFFFFFF), '08X')

        ntp_i  = xml_escape(f"\u20ac{item['ntp']}"       if item.get("ntp")        else "n/a")
        sell_i = xml_escape(f"\xa3{item['sell_price']}"  if item.get("sell_price") else "n/a")
        acp_i  = xml_escape(f"\u20ac{item['acp']}"        if item.get("acp")        else "n/a")
        desc_i = xml_escape(item.get("description",""))
        qty_i  = xml_escape(item.get("qty",""))
        cat_i  = xml_escape(item.get("cat_ref",""))

        def new_cp(*runs):
            return (f'<w:p w14:paraId="{uid()}" w14:textId="77777777">' +
                    '<w:pPr><w:jc w:val="center"/></w:pPr>' +
                    ''.join(runs) + '</w:p>')

        new_desc_block = (
            new_cp(pr(desc_i, bold=True)) +
            new_cp(pr("NTP: "), pr(ntp_i, bold=True)) +
            new_cp(pr("Sell Out: "), pr(sell_i, bold=True)) +
            new_cp(pr("ACP: "), pr(acp_i, bold=True))
        )
        new_qty_block = (
            f'<w:r><w:rPr><w:b/><w:bCs/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr>' +
            f'<w:t>{qty_i}</w:t></w:r>'
        )

        # Build new row by cloning original_row and replacing cell text zones
        # Cell 1: cat_ref — find first <w:tc> in original row
        row = original_row
        tc_starts = [m.start() for m in re.finditer(r'<w:tc[ >]', row)]
        if len(tc_starts) >= 3:
            # Replace cell 1 (cat ref)
            tc1_s = tc_starts[0]; tc1_e = row.find('</w:tc>', tc1_s) + len('</w:tc>')
            tc2_s = tc_starts[1]; tc2_e = row.find('</w:tc>', tc2_s) + len('</w:tc>')
            tc3_s = tc_starts[2]; tc3_e = row.find('</w:tc>', tc3_s) + len('</w:tc>')

            # Preserve <w:tcPr> from original cell, replace para content
            def replace_cell_content(cell_xml, new_paras):
                tcp_m = re.search(r'<w:tcPr>.*?</w:tcPr>', cell_xml, re.DOTALL)
                tcp = tcp_m.group(0) if tcp_m else ''
                tc_tag_end = cell_xml.index('>') + 1
                tc_open = cell_xml[:tc_tag_end]
                return f'{tc_open}{tcp}{new_paras}</w:tc>'

            cell1 = replace_cell_content(row[tc1_s:tc1_e],
                f'<w:p w14:paraId="{uid()}" w14:textId="77777777">' +
                '<w:pPr><w:jc w:val="center"/></w:pPr>' +
                f'<w:r><w:rPr><w:rFonts w:cs="Arial"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr>' +
                f'<w:t>{cat_i}</w:t></w:r></w:p>')
            cell2 = replace_cell_content(row[tc2_s:tc2_e], new_desc_block)
            cell3 = replace_cell_content(row[tc3_s:tc3_e],
                f'<w:p w14:paraId="{uid()}" w14:textId="77777777">' +
                '<w:pPr><w:jc w:val="center"/></w:pPr>' +
                f'{new_qty_block}</w:p>')

            new_row = row[:tc1_s] + cell1 + cell2 + cell3 + row[tc3_e:]
        else:
            log(f"[WARN] Not enough cells in row for item {idx+1}, appending raw")
            new_row = original_row  # fallback: duplicate unchanged

        # Give the <w:tr> a new trPr rsidR to avoid duplicate IDs
        new_row = re.sub(r'w:rsidR="[0-9A-F]+"'
                        , f'w:rsidR="{uid()}"'
                        , new_row, count=1)

        xml = xml[:tr_end] + new_row + xml[tr_end:]

    files["word/document.xml"] = xml.encode("utf-8")
    with zipfile.ZipFile(out_path, 'w', zipfile.ZIP_DEFLATED) as zout:
        for name, b in files.items(): zout.writestr(name, b)
    os.remove(tmp_in)
    log(f"[OK] Filled: {os.path.basename(out_path)}")



if __name__ == "__main__":
    if not QUOTE_PDF or not os.path.exists(QUOTE_PDF):
        log(f"[ERR] Quote PDF not found: {QUOTE_PDF}"); sys.exit(1)
    if not DOCU_PDFS:
        log("[ERR] No valid DOCU_ID PDFs provided"); sys.exit(1)

    log("=" * 55)
    log("  PMO Automation — Vector")
    log(f"  DOCU files: {len(DOCU_PDFS)}")
    log("=" * 55)

    try:
        qdata = extract_quote(QUOTE_PDF)
        if SEQ_OVERRIDE:
            qdata["enquiry_seq"] = SEQ_OVERRIDE
            log(f"[*] Sequence overridden: {SEQ_OVERRIDE}")

        # Extract data from each DOCU_ID PDF
        log(f"[*] Extracting {len(DOCU_PDFS)} DOCU_ID file(s)...")
        raw_items = [extract_price(p) for p in DOCU_PDFS]

        # Step 1: match DOCU items → Quote items (token-based on Designation)
        items = raw_items
        quote_items = extract_quote_items(QUOTE_PDF)
        if quote_items:
            items = match_docu_to_quote(raw_items, quote_items)
        else:
            log("[WARN] No quote items extracted — skipping quote match")

        # Step 2: cross-check sell prices against PO
        if PO_PDF and os.path.exists(PO_PDF):
            po_text = _read_po_text(PO_PDF)
            items   = match_items_to_po(po_text, items)
            for it in items:
                if not it.get("po_ok") and it.get("po_note"):
                    log(f"[!!] {it['po_note']}")
        else:
            log("[WARN] No PO PDF — skipping PO price cross-check")

        cbu = "CBU?????"
        if PMO_LOG and os.path.exists(PMO_LOG):
            try: cbu = get_next_cbu(PMO_LOG); add_pmo_row(PMO_LOG, cbu, qdata)
            except Exception as e: log(f"[WARN] PMO log error: {e}")
        else: log("[WARN] PMO log not found — CBU is placeholder")

        safe_proj = re.sub(r'[\/:*?"<>|]', '', qdata.get("project_name",""))[:50].strip()
        safe_ref  = re.sub(r'[\/:*?"<>|]', '', qdata.get("dwo_ref",""))
        filename  = f"PMO {cbu}-{safe_ref}-{safe_proj}.docx"
        out_path  = os.path.join(os.environ.get("MAGIC_PMO_OUTDIR", tempfile.gettempdir()), filename)

        fill_template(cbu, qdata, items, out_path)

        log(""); log("=" * 55)
        log(f"[OK] CBU:     {cbu}")
        log(f"[OK] File:    {filename}")
        log(f"[OK] Project: {qdata.get('project_name')}")
        log(f"[OK] DWO:     {qdata.get('dwo_ref')}")
        log(f"[OK] Salesman: {qdata.get('salesman')}")
        log(f"[OK] Value:   \xa3{qdata.get('project_value')}")
        # Emit one OK line per item for email table
        for i, it in enumerate(items):
            suf = str(i+1) if i > 0 else ""
            log(f"[OK] CatRef{suf}:  {it.get('cat_ref','')}")
            log(f"[OK] Desc{suf}:    {it.get('description','')}")
            log(f"[OK] Qty{suf}:     {it.get('qty','')}")
            log(f"[OK] NTP{suf}:     \u20ac{it.get('ntp','')}")
            log(f"[OK] SellOut{suf}: \xa3{it.get('sell_price','')}")
            log(f"[OK] ACP{suf}:     \u20ac{it.get('acp','')}")
        print(f"__DOCX__:{out_path}", flush=True)
        sys.exit(0)

    except Exception as e:
        log(f"[ERR] {e}")
        import traceback; traceback.print_exc()
        sys.exit(1)
